import { Meeting, StudentSchedule } from "./types";

/** Parse "HH:MM" into minutes since midnight. */
export const parseTime = (time: string): number => {
  const [hours, minutes] = time.split(":").map(Number);
  return hours * 60 + minutes;
};

/**
 * Two meetings conflict if they share a day and their time ranges overlap.
 * (Adjacent meetings -- one ending exactly when the other starts -- do NOT
 * conflict.)
 */
export const meetingsOverlap = (a: Meeting, b: Meeting): boolean => {
  const sameDay = a.days.some((active, i) => active && b.days[i]);
  if (!sameDay) return false;

  const startA = parseTime(a.startTime);
  const endA = parseTime(a.endTime);
  const startB = parseTime(b.startTime);
  const endB = parseTime(b.endTime);

  return startA < endB && startB < endA;
};

/**
 * Does this catalog section conflict with anything already on the
 * student's schedule?
 */
export const classConflictsWithSchedule = (
  sectionMeetings: Meeting[],
  schedule: StudentSchedule
): boolean => {
  const scheduleMeetings = schedule.sections.flatMap((s) => s.meetings);

  for (const meeting of sectionMeetings) {
    for (const scheduleMeeting of scheduleMeetings) {
      if (meetingsOverlap(meeting, scheduleMeeting)) return true;
    }
  }

  return false;
};
